#include <vector>
#include <string>
#include <fstream>
#define main original_mixbench_main
#include "../mixbench-cuda/main.cu"
#undef main
int main(){const int n=8*1024*1024,ci=16,r=20,blocks=n/8/128/256;float prior=0;for(int rep=0;rep<r;rep++){float a=prior,b=0;for(int i=0;i<ci;i++){a=a*a+0.1f;b=b*b+0.1f;}prior=((a*b+b*b)+b*b)+b*b;}std::vector<float>expected(n,0),got(n);for(int k=0;k<4;k++)for(int block=0;block<blocks;block++)for(int lane=0;lane<256;lane++)expected[block*256*8+lane+k*blocks*256*8]=prior;float*data;cudaMalloc(&data,n*4);cudaMemset(data,0,n*4);benchmark_func<<<blocks,256>>>(data,ci);cudaDeviceSynchronize();bool all=true;for(int trial=1;trial<=5;trial++){cudaMemset(data,0,n*4);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<r;j++)benchmark_func<<<blocks,256>>>(data,ci);auto error=cudaDeviceSynchronize();double secs=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/r;cudaMemcpy(got.data(),data,n*4,cudaMemcpyDeviceToHost);bool ok=error==cudaSuccess;double maxabs=0;for(int j=0;j<n;j++){double diff=fabs(double(got[j])-expected[j]);ok &=isfinite(got[j])&&diff<=1e-6;maxabs=std::max(maxabs,diff);}all &=ok;std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/output_trial"+std::to_string(trial)+".bin";std::ofstream(path,std::ios::binary).write((char*)got.data(),n*4);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,secs,ok?"true":"false",n,maxabs,r,path.c_str(),n);}puts(all?"PASS":"FAIL");return all?0:1;}
